class Solution:
    def findCircleNum(self, M):
        n = len(M)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]; x = parent[x]
            return x
        for i in range(n):
            for j in range(i + 1, n):
                if M[i][j]:
                    parent[find(i)] = find(j)
        return sum(1 for i in range(n) if find(i) == i)

